    const SvConstBaselineTable *SV_ConstBaselineTable(
        const std::string_view mapName,
        const std::string_view gameType)
    {
        // AN OFF SWITCH, BECAUSE THIS CHANGES WHAT THE CLIENT DRAWS.
        //
        // Arming snapshot flag 0x10 does not merely save bandwidth: the client
        // resolves every static entity against the baseline, so any field this
        // server does NOT model now inherits RETAIL'S value where it previously
        // got a zero. That is the point -- and it is also a rendering change, so
        // it needs a way to be taken back. Without one, "is this new?" costs a
        // rebuild and a cycle instead of one env var.
        //
        // OLMOD_CONST_BASELINES=0 falls back to sequential numbering with the
        // flag off, which is what every build before this one did.
        static const auto enabled = [] {
            const auto *const value = std::getenv("OLMOD_CONST_BASELINES");
            return !value || !*value || *value != '0';
        }();
        if (!enabled)
            return nullptr;
        const SvConstBaselineTable *mapOnly = nullptr;
        for (const auto &table : Tables)
        {
            if (table.mapName != mapName)
                continue;
            if (table.gameType == gameType)
                return &table;
            if (!mapOnly)
                mapOnly = &table;
        }
        return mapOnly;
    }
